action_details.action_postfix:
// Physical nexus established - filing required
true result.in_has_nexus xdef
"Indiana filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.in_has_nexus xdef
"Indiana filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Indiana state additions
0.0 /in_additions xdef

// Common Indiana additions:
// - Out-of-state municipal bond interest (acquired after 12/31/2011)
// - Certain expenses related to exempt income

result.in_out_of_state_muni_interest 0.0 ne
{
  in_additions result.in_out_of_state_muni_interest add /in_additions xdef
} if

in_additions result.in_state_additions xdef

// Calculate Indiana state subtractions
0.0 /in_subtractions xdef

// Common Indiana subtractions:
// - IN municipal bond interest
// - State income taxes paid
// - State NOL deduction (if different from federal)

result.in_municipal_interest 0.0 ne
{
  in_subtractions result.in_municipal_interest add /in_subtractions xdef
} if

result.in_state_taxes_paid 0.0 ne
{
  in_subtractions result.in_state_taxes_paid add /in_subtractions xdef
} if

in_subtractions result.in_state_subtractions xdef

"Indiana additions: $" result.in_state_additions cvs strconcat ", subtractions: $" strconcat result.in_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Indiana taxable income // Federal taxable income apportioned to IN + additions - subtractions result.in_apportioned_income result.in_state_additions add result.in_state_subtractions sub 0.0 max result.in_taxable_income xdef
// Calculate Indiana tax using flat rate: 4.9% result.in_taxable_income result.in_corp_tax_rate mul /in_tax_before_credits xdef
// Subtract Indiana state credits in_tax_before_credits result.in_state_credits sub 0.0 max result.in_tax_liability xdef
// Calculate refund or amount owed result.in_estimated_payments result.in_tax_liability sub result.in_refund_or_owed xdef
"Indiana taxable income: $" result.in_taxable_income cvs strconcat job.audit_trail swap addto "Indiana tax liability (4.9%): $" result.in_tax_liability cvs strconcat job.audit_trail swap addto
